3	/**
4	 * Single source of truth for the owner-telephone normalization rule: strip every non-digit
5	 * character. Both {@link ValidateOwnerFields} (which normalizes the submitted value) and
6	 * {@link CheckOwnerTelephoneUnique} (which compares against stored owners) use this so the two can
7	 * never drift apart.
8	 */
9	final class OwnerTelephone {
10	
11	    private OwnerTelephone() {
12	    }
13	
14	    static String normalize(String value) {
15	        return value == null ? "" : value.replaceAll("\\D", "");
16	    }
17	}
