1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create request whose normalized telephone is already used by any other owner.
10	 *
11	 * <p>Runs after {@link ValidateOwnerFields} and before {@link BuildOwner}. Both the request and
12	 * every stored owner's telephone are reduced through the shared {@link OwnerTelephone#normalize}
13	 * rule before comparison, so differently formatted numbers that collapse to the same digits still
14	 * collide. A match throws {@link OwnerTelephoneInUseException}, handled as a 409 Conflict.
15	 */
16	public class CheckOwnerTelephoneUnique {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws OwnerTelephoneInUseException {
20	        String telephone = OwnerTelephone.normalize(request.getTelephone());
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (telephone.equals(OwnerTelephone.normalize(existing.getTelephone()))) {
23	                throw new OwnerTelephoneInUseException(request.getTelephone());
24	            }
25	        }
26	    }
27	}
