3	/**
4	 * Thrown by {@link CheckOwnerTelephoneUnique} when a create request carries a normalized telephone
5	 * that is already used by another owner. Handled globally by
6	 * {@code OwnerTelephoneInUseExceptionHandler}, which responds 409 Conflict.
7	 */
8	public class OwnerTelephoneInUseException extends Exception {
9	
10	    private final String telephone;
11	
12	    public OwnerTelephoneInUseException(String telephone) {
13	        super("Telephone already in use: " + telephone);
14	        this.telephone = telephone;
15	    }
16	
17	    public String getTelephone() {
18	        return telephone;
19	    }
20	}
